var subtitleInspectorView = newLocalizedTemplate("subtitle-inspector", subtitleInspectorHTML)

func (manager *subtitleManager) subtitleInspectorWeb(writer http.ResponseWriter, request *http.Request) {
	language, _, err := manager.reviewQuery(request, false)
	if err != nil {
		localizedError(writer, request, err.Error(), http.StatusBadRequest)
		return
	}
	review, status, err := manager.inspectSubtitle(request, request.PathValue("id"), language)
	if err != nil {
		localizedError(writer, request, err.Error(), status)
		return
	}
	_, _, languages := subtitleLanguageViews([]string{language})
	data := struct {
		Review    subtitleReview
		Languages []subtitleLanguageOption
		Encodings []string
	}{review, languages, subtitleEncodings}
	writer.Header().Set("Content-Type", "text/html; charset=utf-8")
	if err = subtitleInspectorView.Execute(writer, request, data); err != nil {
		localizedError(writer, request, "subtitle inspector is unavailable", http.StatusInternalServerError)
	}
}
